window.BOOK={"key":"harith","app":"mutoon-harith","lsk":"mutoon_harith_v1","prefix":"ha_","title":"معلقة الحارث بن حلزة","sub":"معلقة · الحارث بن حلزة اليشكري (ت نحو ٥٧٠م) · ٨٢ بيتًا","poems":[{"id":"harith","title":"معلقة الحارث بن حلزة","nazim":"الحارث بن حلزة اليشكري","death":"ت نحو ٥٧٠م","meter":"الخفيف","source":"المكتبة الشاملة: شرح المعلقات السبع للزوزني (دار إحياء التراث العربي، ط١ ١٤٢٣هـ)","srcUrl":"https://shamela.ws/book/11253/290","note":"نص المعلقة برواية الزوزني وعدّه وترتيبه (٨٢ بيتًا)، قوبل كلمةً كلمةً بسكربت بشرح القصائد العشر للتبريزي وشرح القصائد السبع لابن الأنباري. أُكمل الشكل من الشرحين حيث اتفقت الكلمة، وصُحّحت أخطاء الطبع والوزن، وكل ذلك في تقرير المصادر.","verses":[["آذَنَتْنَا بِبَينِهَا أَسْمَاءُ","رُبَّ ثَاوٍ يُمَلُّ مِنْهُ الثَّوَاءُ"],["بَعْدَ عَهْدٍ لَهَا بِبُرْقَةِ شَمَّا","ءَ فَأَدْنَى دِيَارِهَا الْخَلْصَاءُ"],["فَالْمُحَيَّاةُ فَالصِّفَاحُ فَأَعْنَا","قُ فِتَاقٍ فَعَاذِبٌ فَالْوَفَاءُ"],["فَرِيَاضُ الْقَطَا فَأَوْدِيَةُ الشُّرْ","بُبِ فَالشُّعْبَتَانِ فَالْأَبْلَاءُ"],["لَا أَرَى مَنْ عَهِدْتُ فِيهَا فَأَبْكِي الْ","يَوْمَ دَلْهًا وَمَا يُحِيرُ الْبُكَاءُ"],["وَبِعَيْنَيْكَ أَوْقَدَتْ هِنْدٌ النَّا","رَ أَخيرًا تُلْوِي بِهَا الْعَلْيَاءُ"],["فَتَنَوَّرْتُ نَارَهَا مِنْ بَعِيدٍ","بِخَزَازَى هَيْهَاتَ مِنْكَ الصِّلَاءُ"],["أَوْقَدَتْهَا بَيْنَ الْعَقِيقِ فَشَخْصَيْ","نِ بِعُودٍ كَمَا يَلُوحُ الضِّيَاءُ"],["غَيْرَ أَنِّي قَدْ أَسْتَعِينُ عَلَى الْهَمِّ","إِذَا خَفَّ بِالثَّوِيِّ النَّجَاءُ"],["بِزَفُوفٍ كَأَنَّهَا هِقْلَةٌ أُ","مُّ رِئَالٍ دَوِّيَّةٍ سَقْفَاءُ"],["آنَسَتْ نَبْأَةً وَأَفْزَعَهَا الْقُ","نَّاصُ عَصْرًا وَقَدْ دَنَا الْإِمْسَاءُ"],["فَتَرَى خَلْفَهَا مِنَ الرَّجْعِ وَالْوَقْ","عِ مَنِينًا كَأَنَّهُ إِهْبَاءُ"],["وَطِرَاقًا مِنْ خَلْفِهِنَّ طِرَاقٌ","سَاقِطَاتٌ أَلْوَتْ بِهَا الصَّحْرَاءُ"],["أَتَلَهَّى بِهَا الْهَوَاجِرَ إِذْ كُلُّ","ابْنِ هَمٍّ بَلِيَّةٌ عَمْيَاءُ"],["وَأَتَانَا مِنَ الْحَوَادِثِ وَالْأَنْبَا","ءِ خَطْبٌ نُعْنَى بِهِ وَنُسَاءُ"],["إِنّ إِخْوَانَنَا الْأَرَاقِمَ يَغْلُو","نَ عَلَيْنَا فِي قِيلِهِمْ إِحْفَاءُ"],["يَخْلِطُونَ الْبَرِيءَ مِنَّا بِذِي الذَّنْ","بِ وَلَا يَنْفَعُ الْخَلِيَّ الْخَلَاءُ"],["زَعَمُوا أَنَّ كُلَّ مَنْ ضَرَبَ الْعَيْ","رَ مُوَالٍ لَنَا وَأَنَّا الْوَلَاءُ"],["أَجْمَعُوا أَمْرَهُمْ عِشَاءً فَلَمَّا","أَصْبَحُوا أَصْبَحَتْ لَهُمْ ضَوْضَاءُ"],["مِنْ مُنَادٍ وَمِنْ مُجِيبٍ وَمِنْ تَصْ","هَالِ خَيْلٍ خِلَالَ ذَاكَ رُغَاءُ"],["أَيُّهَا النَّاطِقُ الْمُرَقِّشُ عَنَّا","عِنْدَ عَمْرٍو وَهَلْ لِذَاكَ بَقَاءُ"],["لَا تَخَلْنَا عَلَى غَرَاتِكَ إِنَّا","قَبْلُ مَا قَدْ وَشَى بِنَا الْأَعْدَاءُ"],["فَبَقِينَا عَلَى الشَّنَاءَةِ تَنْمِي","نَا حُصُونٌ وَعِزَّةٌ قَعْسَاءُ"],["قَبْلَ مَا الْيَوْمِ بَيَّضَتْ بِعُيُونِ النَّ","اسِ فِيهَا تَغَيُّظٌ وَإِبَاءُ"],["وَكَأَنَّ الْمَنُونَ تَرْدِي بِنَا أَرْ","عَنَ جَوْنًا يَنْجَابُ عَنْهُ الْعَمَاءُ"],["مُكْفَهِرًّا عَلَى الْحَوَادِثِ لَا تَرْ","تُوهُ لِلدَّهْرِ مُؤْيِدٌ صَمَّاءُ"],["إِرَمِيٌّ بِمِثْلِهِ جَالَتِ الْخَيْ","لُ وَتَأبَى لِخَصْمِهَا الْإِجْلَاءُ"],["مَلِكٌ مُقْسِطٌ وَأَفْضَلُ مَنْ يَمْ","شِي وَمِنْ دُونِ مَا لَدَيْهِ الثَّنَاءُ"],["أَيُّمَا خُطَّةٍ أَرَدْتُمْ فَأَدُّو","هَا إِلَيْنَا تُشْفَى بِهَا الْأَمْلَاءُ"],["إِنْ نَبَشْتُمْ مَا بَيْنَ مِلْحَةَ فَالصَّا","قِبِ فِيهِ الْأَمْوَاتُ وَالْأَحْيَاءُ"],["أَوْ نَقَشْتُمْ فَالنَّقْشُ يَجْشَمَهُ النَّا","سُ وَفِيهِ الْإِسْقَامُ وَالْإِبْرَاءُ"],["أَوْ سَكَتُّمْ عَنَّا فَكَنَّا كَمَنْ أَغْ","مَضَ عَيْنًا فِي جَفْنِهَا الْأَقْذَاءُ"],["أَوْ مَنَعْتُمْ مَا تُسْأَلُونَ فَمَنْ حُدِّ","ثْتُمُوهُ لَهُ عَلَيْنَا الْعَلَاءُ"],["هَلْ عَلِمْتُمْ أَيَّامَ يُنْتَهَبُ النَّا","سُ غِوَارًا لِكُلِّ حَيٍّ عُوَاءُ"],["إِذْ رَفَعْنَا الْجِمَالَ مِنْ سَعَفِ الْبَحْ","رَيْنِ سَيْرًا حَتَّى نَهَاهَا الْحِسَاءُ"],["ثُمَّ مِلْنَا عَلَى تَمِيمٍ فَأَحْرَمْ","نَا وَفِينَا بَنَاتُ قَوْمٍ إِمَاءُ"],["لَا يُقِيمُ الْعَزِيزُ بِالْبَلَدِ السَّهْ","لِ وَلَا يَنْفَعُ الذَّلِيلَ النَّجَاءُ"],["لَيْسَ يُنْجِي الّذِي يُوَائِل مِنّا","رَأْسُ طَوْدٍ وَحَرَّةٌ رَجْلَاءُ"],["مَلِكٌ أَضْرَعَ الْبَرِيَّةِ لَا يُو","جَدُ فِيهَا لِمَا لَدَيْهِ كِفَاءُ"],["كَتَكَالِيفِ قَوْمِنَا إِذْ غَزَا الْمُنْ","ذِرُ هَلْ نَحْنُ لابْنِ هِنْدٍ رِعَاءُ"],["مَا أَصَابُوا مِنْ تَغْلَبِيٍّ فَمَطْلُو","لٌ عَلَيْهِ إِذَا أُصِيبَ الْعَفَاءُ"],["إِذْ أَحَلَّ الْعَلْيَاءَ قُبَّةَ مَيْسُو","نَ فَأَدْنَى دِيَارِهَا الْعَوْصَاءُ"],["فَتَأَوَّتْ لَهُ قَرَاضِبَةٌ مِنْ","كُلِّ حَيٍّ كَأَنَّهُمْ أَلْقَاءُ"],["فَهَدَاهُمْ بِالْأَسْوَدَيْنِ وَأَمْرُ اللَّهِ","بِلْغٌ تَشْقَى بِهِ الْأَشْقِيَاءُ"],["إِذْ تَمَنَّوْنَهُمْ غُرُورًا فَسَاقَتْ","هُمْ إِلَيْكُمْ أُمْنِيَّةٌ أَشْرَاءُ"],["لَمْ يَغُرُّوكُمُ غُرُورًا وَلَكِنْ","رَفَعَ الآلُ شَخْصَهُم وَالضَّحَاءُ"],["أَيُّهَا النّاطِقُ الْمُبَلِّغُ عَنَّا","عِنْدَ عَمْرٍو وَهَلْ لِذَاكَ انْتِهَاءُ"],["مَنْ لَنَا عِنْدَهُ مِنَ الْخَيْرِ آيَا","تٌ ثَلَاثٌ فِي كُلِّهِنَّ الْقَضَاءُ"],["آيَةٌ شَارِقُ الشَّقِيقَةِ إِذْ جَا","ءَتْ مَعَدٌّ لِكُلِّ حَيٍّ لِوَاءُ"],["حَوْلَ قَيْسٍ مُسْتَلْئِمِينَ بِكَبْشٍ","قَرَظِيٍّ كَأَنَّهُ عَبْلَاءُ"],["وَصَتِيتٍ مِنَ الْعَوَاتِكِ لَا تَنْ","هَاهُ إِلَّا مُبْيَضَّةٌ رَعْلَاءُ"],["فَرَدَدْنَاهُمُ بِطَعْنٍ كَمَا يَخْ","رُجُ مِنْ خُرْبَةِ الْمَزَادِ الْمَاءُ"],["وَحَمَلْنَاهُمُ عَلَى حَزْمِ ثَهْلَا","نَ شِلَالًا وَدُمِّيَ الْأَنْسَاءُ"],["وَجَبَهْنَاهُمُ بِطَعْنٍ كَمَا تُنْ","هَزُ فِي جَمَّةِ الطَّوِيِّ الدِّلَاءُ"],["وَفَعَلْنَا بِهِمْ كَمَا عَلِمَ اللَّهُ","وَمَا إِنْ لِلْحَائِنِينَ دِمَاءُ"],["ثُمَّ حُجْرًا أَعْنِي ابْنَ أُمِّ قَطَامِ","وَلَهُ فَارِسِيَّةٌ خَضْرَاءُ"],["أَسَدٌ فِي اللِّقَاءِ وَرْدٌ هَمُوسٌ","وَرَبِيعٌ إِنْ شَمّرَتْ غَبْرَاءُ"],["وَفَكَكْنَا غُلَّ امْرِئِ الْقَيْسِ عَنْهُ","بَعْدَمَا طَالَ حَبْسُهُ وَالْعَنَاءُ"],["وَمَعَ الْجَوْنِ جَوْنِ آلِ بَنِي الْأَوْ","سِ عَنُودٌ كَأَنَّهَا دَفْوَاءُ"],["مَا جَزِعْنَا تَحْتَ الْعَجَاجَةِ إِذْ وَلَّ","وْا شِلَالًا وَإِذْ تَلَظّى الصِّلَاءُ"],["وَأَقَدْنَاهُ رَبَّ غَسَّانَ بِالْمُنْ","ذِرِ كَرْهًا إِذْ لَا تُكَالُ الدِّمَاءُ"],["وَأَتَيْنَاهُمُ بِتِسْعَةِ أَمْلَا","كٍ كِرَامٍ أَسْلَابُهُمْ أَغْلَاءُ"],["وَوَلَدْنَا عَمْرَو بْنَ أُمِّ أُنَاسٍ","مِنْ قَرِيبٍ لَمَّا أَتَانَا الْحِبَاءُ"],["مِثْلُهَا تُخْرِجُ النَّصِيحَةَ لِلْقَوْ","مِ فَلَاةٌ مِنْ دُونِهَا أَفْلَاءُ"],["فَاتْرُكُوا الطَّيْخَ وَالتَّعَاشِي وَإِمَّا","تَتَعَاشَوْا فَفِي التَّعَاشِي الدَّاءُ"],["وَاذْكُرُوا حِلْفَ ذِي الْمَجَازِ وَمَا قُدِّ","مَ فِيهِ الْعُهُودُ وَالْكُفَلَاءُ"],["حَذَرَ الْجَوْرِ وَالتَّعَدِّي وَهَلْ يَنْ","قُضُ مَا فِي الْمَهَارِقِ الْأَهْوَاءُ"],["وَاعْلَمُوا أَنَّنَا وَإِيَّاكُمْ فِي","مَا اشْتَرَطْنَا يَوْمَ اخْتَلَفْنَا سَوَاءُ"],["عَنَنًا بَاطِلًا وَظُلْمًا كَمَا تُعْ","تَرُ عَنْ حَجْرَةِ الرَّبِيضِ الظِّبَاءُ"],["أَعَلَيْنَا جُنَاحُ كِنْدَةَ أَنْ يَغْ","نَمَ غَازِيهِمُ وَمِنَّا الْجَزَاءُ"],["أَمْ عَلَيْنَا جَرَّى إِيَادٍ كَمَا نِي","طَ بِجَوْزِ الْمُحَمَّلِ الْأَعْبَاءُ"],["لَيْسَ مِنَّا الْمَضَرَّبُونَ وَلَا قَيْ","سٌ وَلَا جَنْدَلٌ وَلَا الْحَدَّاءُ"],["أَمْ جَنَايَا بَنِي عَتِيقٍ فَإِنَّا","مِنْكُمُ إِنْ غَدَرْتُمُ بُرَآءُ"],["وَثَمَانُونَ مِنْ تَمِيمٍ بِأَيْدِي","هِمْ رِمَاحٌ صُدُورُهُنَّ الْقَضَاءُ"],["تَرَكُوهُمْ مُلَحَّبِينَ وَآبُوا","بِنِهَابٍ يُصِمُّ مِنْهَا الْحُدَاءُ"],["أَمْ عَلَيْنَا جَرَّى حَنِيفَةَ أَمْ مَا","جَمَّعَتْ مِنْ مُحَارِبٍ غَبْرَاءُ"],["أَمْ عَلَيْنَا جَرَّى قُضَاعَةَ أَمْ لَيْ","سَ عَلَيْنَا فِيمَا جَنَوْا أَنْدَاءُ"],["ثُمَّ جَاءُوا يَسْتَرْجِعُونَ فَلَمْ تَرْ","جِعْ لَهُمْ شَامَةٌ وَلَا زَهْرَاءُ"],["لَمْ يُحِلّوا بَنِي رِزَاحٍ بِبَرْقَا","ءِ نِطَاعٍ لَهُمْ عَلَيْهِمْ دُعَاءُ"],["ثُمَّ فَاءُوا مِنْهُمْ بِقَاصِمَةِ الظَّهْ","رِ وَلَا يَبْرُدُ الْغَلِيلَ الْمَاءُ"],["ثُمَّ خَيْلٌ مِنْ بَعْدِ ذَاكَ مَعَ الْغَلّا","قِ لَا رَأْفَةٌ وَلَا إِبْقَاءُ"],["وَهُوَ الرَّبُّ وَالشَّهِيدُ عَلَى يَوْ","مِ الْحِيَارَيْنِ وَالْبَلَاءُ بَلَاءُ"]],"secs":{"1":"معلقة الحارث بن حلزة"}}],"sharh":false};
